#!/usr/bin/env python3
from pathlib import Path
import base64, json, py_compile, subprocess, sys, tempfile
REQUIRED={'winapk_UCRT_CD_Clang_Fix5.py': 'windows/host/native_usb_cd.cpp', 'winapk_UCRT_CD_Clang_Fix8B.py': 'windows/host/ucrt_cd_bridge.h'}
ORDER=['winapk_UCRT_CD_Clang_Fix.py', 'winapk_UCRT_CD_Clang_Fix2.py', 'winapk_UCRT_CD_Clang_Fix3.py', 'winapk_UCRT_CD_Clang_Fix5.py', 'winapk_UCRT_CD_Clang_Fix6.py', 'winapk_UCRT_CD_Clang_Fix7.py', 'winapk_UCRT_CD_Clang_Fix8B.py', 'HostDocumentsProvider_WindowsTreeFix.py', 'winapk_UCRT_Runtime_Diagnostic.py', 'winapk_UCRT_Runtime_Stage_Fix.py']
SCRIPTS=json.loads(base64.b64decode('').decode())

def find_root(start):
 start=Path(start).resolve()
 for c in (start,*start.parents):
  if (c/"windows/CMakeLists.txt").is_file() and (c/"runtime").is_dir(): return c
 for p in start.rglob("windows/CMakeLists.txt"):
  c=p.parent.parent
  if (c/"runtime").is_dir(): return c
 raise FileNotFoundError("win.apk-main project root was not found")

def main():
 root=find_root(sys.argv[1] if len(sys.argv)>1 else Path.cwd())
 print(f"[ROOT] {root}")
 with tempfile.TemporaryDirectory(prefix="winapk-all-fixes-") as td:
  td=Path(td)
  for i,name in enumerate(ORDER,1):
   print(f"\n[{i}/{len(ORDER)}] {name}")
   required = REQUIRED.get(name)
   if required and not (root / required).is_file():
    print(f"[SKIP] Optional component is not present: {required}")
    continue
   p=td/name; p.write_text(SCRIPTS[name],encoding="utf-8",newline="\n")
   py_compile.compile(str(p),doraise=True)
   subprocess.run([sys.executable,str(p),str(root)],cwd=root,check=True)
 print("\n[OK] All applicable Win.apk UCRT fixes were applied consistently.")
 print("[NEXT] Install deps once: ./windows/scripts/install-clang-build-deps.sh")
 print("[NEXT] Build: ./windows/scripts/build-windows-clang.sh")
 return 0
if __name__=="__main__": raise SystemExit(main())
